-- PROPOSITION SEULEMENT, NON APPLIQUEE (ERP Mortier 2026-10-27)
-- ALIGNEMENT des privileges directs service_role sur TEST.
-- Evaluer la compatibilite des parcours ERP deployes avant execution.
DO $guard$ BEGIN
 IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')) <> 70 THEN RAISE EXCEPTION 'Safety stop: table count'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND NOT c.relrowsecurity) THEN RAISE EXCEPTION 'Safety stop: RLS'; END IF;
END $guard$;
REVOKE SELECT ON TABLE public."appels_offres", public."contrats", public."devis", public."erreurs", public."feuilles_de_temps", public."fiches_de_paie", public."grilles_tarifaires", public."lignes_devis", public."lignes_factures_fournisseurs", public."logs", public."parametres", public."projets", public."reponses_appels_offres", public."taches" FROM service_role;
